//获取福利礼包
function getfllq(id){
	var ts=event.currentTarget;
   
    var clickattr = $(ts).attr("onclick");
    $(ts).removeAttr("onclick");
    $.getJSON("/Ticket/receive/?id="+id+"&token="+token,function(data){
    	  if(data.code==="1"){
    	  	  alert('领取成功');
			     console.log('01领取成功');
			 $(ts).removeAttr("onclick").addClass('no').html('已领取');
    	  	 // $(ts).attr("onclick",clickattr).addClass('no').html('已领取');
    	  	  return true;
    	  }else if(data.code==="-1"){
    	  	  $(ts).removeAttr("onclick").addClass('no').html('已领取');
    	  }
    	  alert(data.msg);
    	  return true;
    });
    
}


