 var pagestatus = 0;
function nextpage(){
	if(pagestatus==1){
		return false;
	}
	pagestatus=1;
	var downloadsPage = $("#downloadsPage").val();

	downloadsPage = parseInt(downloadsPage)+1;
	$("#downloadsPage").attr("value",downloadsPage);

	var parm = "&pageSize=10&isopen=sdk&order=weight&page="+downloadsPage;
	//$.getJSON("http://h5.m."+domain+"/index.php?m=Apisdk&a=getGameList&callback=?"+parm,function(data){
   	$.getJSON("/Apisdk/geth5lists/?"+parm,function(data){
	 	pagestatus=0;
		if(data.lists){
			var str = '';
			$.each(data.lists,function(i,item){
				if(item.sdkid==0){
					return true;
				}
				str += '<li onclick="topUrl(\''+item.sdkid+'\')"><img src="'+item.icon+'" /><div class="mc"><h2>'+item.shorttitle+'</h2><b>'+item.remark+'</b></div><a target="_top" href="http://sdkh5.'+domain+'/game/'+item.sdkid+'/'+channel+'/">开始</a></li>'
						
			});
			$("#content_list_div").append(str);
		}
		//alert(data.status)
		if(data.status=='0'){
			$("#content_more_div").hide();
		}
	 });
}